import { unstable_cache, revalidateTag } from 'next/cache'

export async function getAllProducts() {
  await new Promise((resolve) => setTimeout(resolve, 100))

  return [
    { id: 1, name: 'Laptop', price: 999 },
    { id: 2, name: 'Phone', price: 699 },
    { id: 3, name: 'Tablet', price: 499 },
    { id: 4, name: 'Headphones', price: 199 },
    { id: 5, name: 'Watch', price: 299 },
  ]
}

let lastSyncedAt = new Date().toISOString()

export async function getCatalog() {
  const products = await getAllProducts()
  return { products, lastSyncedAt }
}

export const getCachedCatalog = unstable_cache(
  getCatalog,
  ['catalog'],
  { tags: ['products'] },
)

export async function syncCatalog() {
  await new Promise((resolve) => setTimeout(resolve, 5000))
  lastSyncedAt = new Date().toISOString()
  revalidateTag('products')
}

import type { Metadata } from 'next'
import { after } from 'next/server'
import { getCachedCatalog, syncCatalog } from '@/lib/db'

export const metadata: Metadata = {
  title: 'Product Catalog',
}

async function syncAction() {
  'use server'
  after(() => syncCatalog())
}

export default async function Page() {
  const { products, lastSyncedAt } = await getCachedCatalog()

  return (
    <main>
      <header>
        <h1>Product Catalog</h1>
        <form action={syncAction}>
          <button type="submit">Sync latest catalog</button>
        </form>
        <p>Last synced: {lastSyncedAt}</p>
      </header>
      <ul>
        {products.map((p) => (
          <li key={p.id}>
            {p.name} — ${p.price}
          </li>
        ))}
      </ul>
    </main>
  )
}
